begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('33333333-3333-4333-8333-333333333333','duplicate-alice@example.test'),
 ('44444444-4444-4444-8444-444444444444','duplicate-bob@example.test');
set local role anon;
select throws_ok($$select public.duplicate_idea_project('11111111-1111-4111-8111-111111111111','{"expectedRevision":1}','qa-duplicate-key-0001')$$,'42501',null,'Anonymous duplication denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select set_config('test.source',public.create_idea_project('{"title":"Source","brief":"Explain rain","referenceText":"Source notes","targetDurationMs":90000,"tone":"direct","audienceLevel":"advanced"}','qa-create-source-0001')::text,true);
reset role;
update public.project_revisions set settings='{"voice":"male","captions":true,"theme":"topic"}' where project_id=(current_setting('test.source')::jsonb->>'id')::uuid;
set local role authenticated;
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{}','qa-duplicate-key-0001')$$,'P0001','VALIDATION_FAILED','Revision required');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":"1"}','qa-duplicate-key-0001')$$,'P0001','VALIDATION_FAILED','Revision must be numeric');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1,"owner_id":"other"}','qa-duplicate-key-0001')$$,'P0001','VALIDATION_FAILED','Ownership input rejected');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','short')$$,'P0001','VALIDATION_FAILED','Bounded key required');
select set_config('test.copy',public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','qa-duplicate-key-0001')::text,true);
select isnt(current_setting('test.copy')::jsonb->>'id',current_setting('test.source')::jsonb->>'id','Copy has separate identity');
select is(current_setting('test.copy')::jsonb->>'title','Copy of Source','Copy title is descriptive');
select is((current_setting('test.copy')::jsonb->>'revision')::integer,1,'Copy starts at revision one');
select is(current_setting('test.copy')::jsonb->>'brief','Explain rain','Idea copied');
select is(current_setting('test.copy')::jsonb->>'referenceText','Source notes','Notes copied');
select is(current_setting('test.copy')::jsonb->>'targetDurationMs','90000','Duration copied');
select is(current_setting('test.copy')::jsonb->>'audienceLevel','advanced','Audience copied');
select is(current_setting('test.copy')::jsonb->>'tone','direct','Tone copied');
select is(current_setting('test.copy')::jsonb->'settings','{"voice":"male","captions":true,"theme":"topic"}'::jsonb,'Settings snapshot copied');
select is((select count(*)::integer from public.project_revisions where project_id=(current_setting('test.copy')::jsonb->>'id')::uuid),1,'Source history is not cloned');
select is(public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','qa-duplicate-key-0001'),current_setting('test.copy')::jsonb,'Retry returns original acknowledgement');
select is((select count(*)::integer from public.projects),2,'Replay does not create another copy');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','qa-duplicate-key-0001')$$,'P0001','IDEMPOTENCY_CONFLICT','Same key changed body rejected');
select set_config('test.changed',public.save_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1,"brief":"Source changed"}','qa-save-source-0001')::text,true);
select is(public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','qa-duplicate-key-0001'),current_setting('test.copy')::jsonb,'Replay works after source changes');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','qa-duplicate-stale-0001')$$,'P0001','REVISION_CONFLICT','Fresh stale copy rejected');
select is(public.get_idea_project((current_setting('test.copy')::jsonb->>'id')::uuid)->>'brief','Explain rain','Source edit does not mutate copy');
select set_config('test.copyedited',public.save_idea_project((current_setting('test.copy')::jsonb->>'id')::uuid,'{"expectedRevision":1,"referenceText":"Copy notes"}','qa-save-copy-000001')::text,true);
select is(public.get_idea_project((current_setting('test.source')::jsonb->>'id')::uuid)->>'referenceText','Source notes','Copy edit does not mutate source');
select set_config('request.jwt.claims','{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated"}',true);
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','qa-duplicate-key-0001')$$,'P0001','RESOURCE_NOT_FOUND','Foreign duplication concealed');
select is((select count(*)::integer from public.projects),0,'Foreign copies remain invisible');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select set_config('test.unicode',public.create_idea_project(jsonb_build_object('title',repeat('😀',70)),'qa-unicode-source-01')::text,true);
select set_config('test.unicodecopy',public.duplicate_idea_project((current_setting('test.unicode')::jsonb->>'id')::uuid,'{"expectedRevision":1}','qa-unicode-copy-0001')::text,true);
select is((select sum(case when ascii(ch)>65535 then 2 else 1 end)::integer from regexp_split_to_table(current_setting('test.unicodecopy')::jsonb->>'title','') ch),140,'Long Unicode title stays within browser length limit');
reset role;
update public.projects set deleted_at=now() where id=(current_setting('test.source')::jsonb->>'id')::uuid;
set local role authenticated;
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','qa-deleted-copy-0001')$$,'P0001','RESOURCE_NOT_FOUND','Tombstoned source cannot be copied');
reset role;
update public.profiles set deletion_status='pending' where owner_id='33333333-3333-4333-8333-333333333333';
set local role authenticated;
select throws_ok($$select public.duplicate_idea_project((current_setting('test.copy')::jsonb->>'id')::uuid,'{"expectedRevision":2}','qa-inactive-copy-001')$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive owner cannot copy');
select * from finish();
rollback;
